const test=require('node:test');
const assert=require('node:assert/strict');
const {probe}=require('../rules.cjs');
test('global reuse and saved index',()=>{
  const rule=/cat/gi; rule.lastIndex=4;
  for(let i=0;i<3;i++) {
    assert.equal(probe(rule,'Cat cat'),true);
    assert.equal(rule.lastIndex,4);
  }
  assert.equal(probe(rule,'dog'),false);
  assert.equal(rule.lastIndex,4);
});
test('sticky remains sticky and starts at zero',()=>{
  const sticky=/cat/y; sticky.lastIndex=2;
  assert.equal(probe(sticky,'xcat'),false);
  assert.equal(probe(sticky,'cat!'),true);
  assert.equal(sticky.lastIndex,2);
  assert.equal(probe(/^.$/u,'🚲'),true);
  assert.equal(probe(/z/,'abc'),false);
});
